package middleware

import (
	"context"
	"errors"

	"github.com/Wei-Shaw/sub2api/internal/service"
	"github.com/gin-gonic/gin"
)

// AdminRoutePolicy binds one exact HTTP method and Gin route template. An empty
// permission is valid only for a SuperAdminOnly capability, never a public route.
type AdminRoutePolicy struct {
	Permission     string
	SuperAdminOnly bool
}

// AdminRoutePolicies returns a detached inventory for coverage checks and review.
func AdminRoutePolicies() map[string]AdminRoutePolicy {
	out := make(map[string]AdminRoutePolicy, len(adminRoutePolicies))
	for key, policy := range adminRoutePolicies {
		out[key] = policy
	}
	return out
}

type adminSnapshotReader interface {
	Snapshot(context.Context, int64) (service.RBACSnapshot, error)
}

// RequireAdminRoutePermission runs AFTER authentication and audit and BEFORE
// compliance, step-up and business handlers. It never infers a permission from a
// URL prefix or HTTP verb. Even a super administrator cannot run an unmapped route.
func RequireAdminRoutePermission(checkers ...PermissionChecker) gin.HandlerFunc {
	var checker PermissionChecker
	if len(checkers) > 0 {
		checker = checkers[0]
	}
	return func(c *gin.Context) {
		subject, ok := GetAuthSubjectFromContext(c)
		if !ok || subject.UserID <= 0 {
			AbortWithError(c, 401, "UNAUTHORIZED", "User not found in context")
			return
		}
		policy, ok := adminRoutePolicies[c.Request.Method+" "+c.FullPath()]
		if !ok || (!policy.SuperAdminOnly && policy.Permission == "") {
			AbortWithError(c, 403, "ADMIN_ROUTE_UNMAPPED", "Management route has no authorization policy")
			return
		}
		if !policy.SuperAdminOnly {
			RequirePermission(checker, policy.Permission)(c)
			return
		}
		if super, ok := c.Get(string(ContextKeySuperAdmin)); ok && super == true {
			c.Next()
			return
		}
		snapshots, ok := checker.(adminSnapshotReader)
		if !ok {
			AbortWithError(c, 503, "RBAC_UNAVAILABLE", "Super administrator checker unavailable")
			return
		}
		snapshot, err := snapshots.Snapshot(c.Request.Context(), subject.UserID)
		if err != nil {
			if errors.Is(err, context.Canceled) {
				AbortWithError(c, 499, "REQUEST_CANCELED", "Request canceled")
			} else {
				AbortWithError(c, 500, "INTERNAL_ERROR", "Failed to evaluate permission")
			}
			return
		}
		if !snapshot.IsSuperAdmin {
			AbortWithError(c, 403, "FORBIDDEN", "Super administrator access required")
			return
		}
		c.Next()
	}
}

